contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool asOwner) public payable {
        address owner = c.owner();
        bool reverted;
        if (asOwner) {
            require(msg.sender == owner);
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
            assert(!reverted);
        } else {
            require(msg.sender != owner);
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        address ownerBefore = c.owner();
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        bool notOwner = msg.sender != ownerBefore;
        bool reverted;

        if (notOwner) {
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        } else {
            c.withdrawAll();
            reverted = false;
        }

        assert(
            (notOwner && reverted && address(c).balance == balBefore && c.owner() == ownerBefore && c.depositsCount() == depositsBefore)
            ||
            (!notOwner && !reverted)
        );
    }

    receive() external payable {}
}

