            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalAfter = address(c).balance;
        uint countAfter = c.depositsCount();

        // The test contract is the owner (it deployed c), so withdrawAll must not revert,
        // must not increment depositsCount, and must transfer c's entire balance away.
