contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint value) public payable {
        uint balBefore = address(c).balance;

        bool reverted;
        try c.withdraw(value) { reverted = false; } catch { reverted = true; }

        uint balAfter = address(c).balance;

        // The owner can withdraw any value up to the contract's balance,
        // unless value is so large that the transfer itself reverts (e.g. amount exceeds uint96).
        // General rule: if the call succeeds then the contract paid exactly `value`;
        // if it reverts then the contract balance is unchanged or the requested value is extreme.
        assert(
            (reverted && (balAfter == balBefore || value > uint256(type(uint96).max))) ||
            (!reverted && balAfter == balBefore - value)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        require(address(this).balance >= value);
        require(msg.sender != address(this));

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        bool reverted;
        try c.sendMoney{value: value}(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        if (msg.sender != c.owner()) {
            assert(reverted);
            assert(afterDeposits == beforeDeposits);
            assert(afterBalance == beforeBalance);
            assert(afterThisBalance == beforeThisBalance);
        } else {
            assert(afterDeposits == beforeDeposits);
            if (reverted) {
                assert(afterBalance == beforeBalance);
                assert(afterThisBalance == beforeThisBalance);
            } else {
                assert(afterBalance == beforeBalance - value);
                assert(afterThisBalance == beforeThisBalance + value);
            }
        }
    }

    receive() external payable {}
}

