contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint dummy) public {
        // Ensure the caller (this contract) is the owner of c.
        require(c.owner() == address(this), "not owner");

        // Send some Ether into c so that a successful withdrawAll is possible.
        uint amount = 1;
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding c failed");

        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        // Drive the public entry under test.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        // General rule: owner call withdrawAll succeeds iff c had Ether; on success c's balance is zero
        // and the owner receives exactly the prior balance of c.
        assert(
            (reverted == (cBalanceBefore == 0)) &&
            (reverted || (cBalanceAfter == 0 && thisBalanceAfter == thisBalanceBefore + cBalanceBefore))
        );
    }

    receive() external payable {}
}

